        <li><p>contacts</p></li>
      </ul>
    </div>
  </div> */}
  <Navig/>
  <div className="header__title"><h1>Vitalii Antonenko</h1></div>
  <div className="header__img">
    <img src={fotoHeader} alt="" />
  </div>
  <div className="header__text"><p>moments of your life</p></div>


  </div>
  
</div>
 </div>
);
}
